package com.wandertrace.service;
import com.wandertrace.exception.*; import java.util.*; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.stereotype.Service;
@Service public class TripAccessService {private final JdbcTemplate db;public TripAccessService(JdbcTemplate db){this.db=db;}public String requireView(UUID userId,UUID tripId){return membership(userId,tripId);}public void requireEdit(UUID userId,UUID tripId){if(!Set.of("OWNER","EDITOR").contains(membership(userId,tripId)))throw new AccessDeniedException();}public void requireOwner(UUID userId,UUID tripId){if(!membership(userId,tripId).equals("OWNER"))throw new AccessDeniedException();}private String membership(UUID userId,UUID tripId){var rows=db.queryForList("select role from trip_members where trip_id=? and user_id=?",tripId,userId);if(rows.isEmpty())throw new AccessDeniedException();return (String)rows.getFirst().get("role");}}
